// ===== 统计工具 =====
export function getWhisperStats() {
  const byCategory: Record<string, number> = {};
  for (const u of BF_WHISPER_UNITS) {
    byCategory[u.category] = (byCategory[u.category] || 0) + 1;
  }
  return {
    total: BF_WHISPER_UNITS.length,
    byCategory,
  };
}

export default BF_WHISPER_UNITS;